using Il2Cpp;
using UnityEngine;
using LastEpochLAN.Mod.OfflineTools;
using System.Text.Json;
int checks=0;
void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS: "+message);}
float Radius(PickupGroundObjectInteraction p)=>((SphereCollider)p.Colliders[0]).radius;
var m=GroundItemManager.instance;var actor=PlayerFinder.Player;
var gold=new GoldPickupInteraction{player=actor};m.activeGoldPiles.Add(gold);
OfflinePickup.Configure(gold);Check(Math.Abs(Radius(gold)-16.8f)<.001,"native gold collider radius x3");
OfflinePickup.Configure(gold);Check(Math.Abs(Radius(gold)-16.8f)<.001,"pooled reinitialisation never multiplies again");
Check(Math.Abs(Radius(m.goldPileSubscriber.Pool.prefabT)-5.6f)<.001,"source prefab remains unchanged");
OfflineToolkit.Settings.Gold=false;OfflinePickup.Refresh();Check(Math.Abs(Radius(gold)-5.6f)<.001,"gold toggle restores original native pickup");
OfflineToolkit.Settings.Gold=true;OfflineToolkit.Ready=false;OfflinePickup.Configure(gold);Check(Math.Abs(Radius(gold)-16.8f)<.001,"native initialization works before character visuals are ready");OfflineToolkit.Ready=true;
var remote=new GoldPickupInteraction{player=new Actor()};OfflinePickup.Configure(remote);Check(Radius(remote)==5.6f,"remote actor untouched");
remote.Colliders[0]=new SphereCollider{radius=16.8f};OfflinePickup.Configure(remote);Check(Radius(remote)==5.6f,"pooled trigger resets native radius before reuse by another actor");
OfflineToolkit.Enabled=false;OfflinePickup.Configure(gold);Check(Radius(gold)==5.6f,"pooled trigger resets native radius before online reuse");OfflineToolkit.Enabled=true;
m.potionSubscriber.Pool.prefabT.Colliders[0]=new SphereCollider{radius=1};var potion=new PotionPickupInteraction{player=actor};OfflinePickup.Configure(potion);Check(Radius(potion)==3,"potion uses its own native base radius");
var bone=new PickupAncientBonesInteraction{player=actor};OfflinePickup.Configure(bone);Check(Math.Abs(Radius(bone)-16.8f)<.001,"bones use native trigger x3");
var other=new OtherPickupInteraction{player=actor};OfflinePickup.Configure(other);Check(Radius(other)==5.6f,"XP/favor and other interactions untouched");
GroundItemVisuals Visual(int type,uint id)=>new(){id=id,itemData=new(){itemType=type},transform=new(){position=new(30,0,40)}};
var key=Visual(100,55);OfflinePickup.Attach(key);var trigger=m.goldPileSubscriber.Active.Single();
Check(!m.goldPileSubscriber.LastInstantiateInactive && trigger.AwakeCompleted,"cold native trigger activates and binds ConditionHandler before initialise");
Check(trigger.gameObject.layer==actor.gameObject.layer,"native pickup collision layer follows the local actor");
Check(trigger.player==actor && trigger.id==55,"key borrows native actor and item id initialization");
Check(trigger.transform.Parent==key.transform && trigger.transform.KeptWorldScale,"key trigger follows actual drop without scaling with item visuals");
Check(key.transform.position.x==30 && key.transform.position.z==40,"drop is not teleported");
Check(trigger.gameObject.Active && Math.Abs(Radius(trigger)-16.8f)<.001,"native key trigger activated at x3 radius");
Check(m.activeGoldPiles.Count==1,"key does not enter native gold accounting list");
Check(m.ItemCalls==0,"creating a drop never grants it");
Check(OfflinePickup.PickUp(gold),"ordinary gold keeps native PickUp implementation");
OfflineToolkit.Settings.Keys=false;OfflinePickup.Refresh();Check(!trigger.Colliders[0].enabled,"disabling keys disables only the key trigger");
Check(!OfflinePickup.PickUp(trigger) && m.ItemCalls==0,"disabled key cannot grant gold or items");
OfflineToolkit.Settings.Keys=true;OfflinePickup.Refresh();Check(trigger.Colliders[0].enabled,"key trigger reenabled from settings");
m.PoolVisual=_=>OfflinePickup.Detach(key);
Check(!OfflinePickup.PickUp(trigger) && m.ItemCalls==1,"key dispatches to native item storage instead of gold");
Check(m.VacuumCalls==0 && OfflinePickup.ItemPickupDepth==0,"auto pickup does not vacuum beyond its triggers");
Check(m.goldPileSubscriber.Active.Count==0 && m.goldPileSubscriber.Released==1,"native visual pooling releases trigger once");
OfflinePickup.Detach(key);Check(m.goldPileSubscriber.Released==1,"repeated cleanup is idempotent");
var material=Visual(101,56);OfflinePickup.Attach(material);trigger=m.goldPileSubscriber.Active.Single();m.PoolVisual=null;m.ThrowOnItem=true;
try{OfflinePickup.PickUp(trigger);throw new Exception("expected exception");}catch(InvalidOperationException){}
Check(OfflinePickup.ItemPickupDepth==0,"native error restores pickup scope");m.ThrowOnItem=false;
OfflinePickup.Attach(material);Check(m.goldPileSubscriber.Active.Count==1,"pooled visual reuse replaces old trigger");
Check(m.goldPileSubscriber.Active.Single().AwakeCompleted,"replacement native trigger also runs Awake before initialization");
OfflinePickup.Attach(Visual(102,57));Check(m.goldPileSubscriber.Active.Count==1,"equipment does not receive auto pickup");
var tutorial=Visual(100,58);tutorial.itemData.Tutorial=true;OfflinePickup.Attach(tutorial);Check(m.goldPileSubscriber.Active.Count==1,"tutorial loot requires native manual interaction");
OfflineToolkit.Enabled=false;OfflinePickup.Attach(Visual(100,59));Check(m.goldPileSubscriber.Active.Count==1,"online item never receives a trigger");OfflineToolkit.Enabled=true;
OfflinePickup.Clear();Check(m.goldPileSubscriber.Active.Count==0,"scene cleanup returns remaining triggers to native pool");
m.pickupItem(actor,100,StackableItemFlags.All);Check(m.VacuumCalls==1,"manual pickup retains the native vacuum");
Check(typeof(OfflinePickup).GetMethods(System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).All(x=>x.Name!="Tick" && x.Name!="Moving"),"no managed frame sweep or movement sampler");
Directory.CreateDirectory("validation");File.WriteAllText("validation/dev55-pickup-awake-fixture.json",JsonSerializer.Serialize(new{passed=true,checks,actualSource="OfflinePickup.cs",nativePhysicsGameplayValidated=false},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"PASS {checks} native pickup fixture checks");
